scope=json.loads(read("v2/experiments/action_executor/r18/source-binding-e3.json"))
inventories={}
for name,folders in [("product",("src","migrations")),("tests",("tests",))]:
 expected=scope["scopes"][name];actual=[]
 for folder in folders:
  for p in (root/"v2/apps/backend"/folder).rglob("*"):
   if {"__pycache__",".pytest_cache",".ruff_cache"}.intersection(p.parts) or p.suffix==".pyc":continue
   assert not p.is_symlink()
   if p.is_file():actual.append(str(p.relative_to(root)))
 actual.extend(n for n in expected if not any("/"+f+"/" in n for f in folders))
 assert sorted(actual)==expected
 digest=hashlib.sha256("".join(pins[n]+"  "+n+"\n" for n in expected).encode()).hexdigest()
 assert digest==scope["digests"][name]
 inventories[name]={"count":len(expected),"digest":digest}
